// Stored ZIP format with CRC32; no external dependency. Max import size is enforced in caller.
const encoder=new TextEncoder(),decoder=new TextDecoder();
const table=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let j=0;j<8;j++)c=c&1?0xedb88320^(c>>>1):c>>>1;table[n]=c>>>0;}
export function crc32(bytes){let c=0xffffffff;for(const b of bytes)c=table[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0;}
function put16(a,i,n){a[i]=n&255;a[i+1]=(n>>>8)&255;}function put32(a,i,n){put16(a,i,n&65535);put16(a,i+2,n>>>16);}
function read16(a,i){return a[i]|a[i+1]<<8;}function read32(a,i){return (read16(a,i)|(read16(a,i+2)<<16))>>>0;}
export function makeZip(entries){const locals=[],central=[];let offset=0;for(const [name,value] of Object.entries(entries)){
 const filename=encoder.encode(name),data=value instanceof Uint8Array?value:encoder.encode(String(value));if(!/^[\w/.-]+$/.test(name)||name.includes('..')||name.startsWith('/'))throw new Error('백업 경로가 올바르지 않습니다.');if(data.length>80_000_000)throw new Error('백업 항목이 너무 큽니다.');
 const crc=crc32(data),local=new Uint8Array(30+filename.length+data.length);put32(local,0,0x04034b50);put16(local,4,20);put16(local,8,0);put32(local,14,crc);put32(local,18,data.length);put32(local,22,data.length);put16(local,26,filename.length);local.set(filename,30);local.set(data,30+filename.length);locals.push(local);
 const cd=new Uint8Array(46+filename.length);put32(cd,0,0x02014b50);put16(cd,4,20);put16(cd,6,20);put32(cd,16,crc);put32(cd,20,data.length);put32(cd,24,data.length);put16(cd,28,filename.length);put32(cd,42,offset);cd.set(filename,46);central.push(cd);offset+=local.length;
 }let cds=central.reduce((n,a)=>n+a.length,0),total=offset+cds+22,out=new Uint8Array(total),pos=0;for(const a of [...locals,...central]){out.set(a,pos);pos+=a.length;}put32(out,pos,0x06054b50);put16(out,pos+8,central.length);put16(out,pos+10,central.length);put32(out,pos+12,cds);put32(out,pos+16,offset);return out;}
export function readZip(bytes){const input=bytes instanceof Uint8Array?bytes:new Uint8Array(bytes);if(input.length>120_000_000)throw new Error('백업이 120MB를 초과합니다.');let pos=0,items={},count=0;while(pos+30<=input.length&&read32(input,pos)===0x04034b50){if(++count>2000)throw new Error('항목 수 제한 초과');const flag=read16(input,pos+6),method=read16(input,pos+8),checksum=read32(input,pos+14),compressed=read32(input,pos+18),length=read32(input,pos+22),nameLength=read16(input,pos+26),extra=read16(input,pos+28);if(flag!==0||method!==0||length!==compressed)throw new Error('지원되지 않는 ZIP 형식입니다. DramaForge에서 내보낸 ZIP을 사용하세요.');const start=pos+30+nameLength+extra,end=start+length;if(end>input.length)throw new Error('백업이 손상되었습니다.');const name=decoder.decode(input.slice(pos+30,pos+30+nameLength));if(!/^[\w/.-]+$/.test(name)||name.includes('..')||name.startsWith('/'))throw new Error('잘못된 백업 파일명');const contents=input.slice(start,end);if(crc32(contents)!==checksum)throw new Error('CRC가 일치하지 않습니다.');items[name]=contents;pos=end;}
 if(!count||!Object.hasOwn(items,'project.json'))throw new Error('project.json을 찾지 못했습니다.');return items;}
export function projectToZip(project){const p=structuredClone(project),entries={};for(const shot of p.shots){if(shot.storyboard?.dataUrl){const match=shot.storyboard.dataUrl.match(/^data:(image\/(?:png|jpeg|webp));base64,(.*)$/s);if(match){const ext=match[1].split('/')[1].replace('jpeg','jpg');const bytes=Uint8Array.from(atob(match[2]),x=>x.charCodeAt(0));const file=`assets/${shot.id}.${ext}`;entries[file]=bytes;shot.storyboard={file,mime:match[1]};}}}entries['project.json']=JSON.stringify(p,null,2);return makeZip(entries);}
export function projectFromZip(bytes){const files=readZip(bytes),p=JSON.parse(decoder.decode(files['project.json']));for(const shot of p.shots||[]){const file=shot.storyboard?.file;if(file){if(!Object.hasOwn(files,file))throw new Error('백업에서 참조 이미지가 누락되었습니다.');const data=files[file];if(data.length>12_000_000)throw new Error('스토리보드 파일이 너무 큽니다.');let raw='';for(let i=0;i<data.length;i+=4096)raw+=String.fromCharCode(...data.slice(i,i+4096));shot.storyboard={mime:shot.storyboard.mime,dataUrl:`data:${shot.storyboard.mime};base64,${btoa(raw)}`};}}return p;}
